import{_ as t,o as l,c as r,j as e,a as n}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第104章 拼团","description":"","frontmatter":{},"headers":[],"relativePath":"第104章_拼团.md","filePath":"第104章_拼团.md"}'),o={name:"第104章_拼团.md"};function s(d,a,_,p,c,i){return l(),r("div",null,[...a[0]||(a[0]=[e("h1",{id:"第104章-拼团",tabindex:"-1"},[n("第104章 拼团 "),e("a",{class:"header-anchor",href:"#第104章-拼团","aria-label":'Permalink to "第104章 拼团"'},"​")],-1),e("p",null,'我们那门生意，是那年冬天做起来的。一开始是她收单，我发货。她说，你只做发货你太亏。我说，我不亏。她说，你发货一单赚一块五，你一个月最多一百八。她说，我这边收单，一单我能挣八块。她说，我把收单分你三成。我说，为什么。她说，因为你收单收不了。我说，那你说这话干什么。她说，我要你跟我一起算这个钱。她说，你只拿发货那一份，你以后跟我对账你永远低一头。她说，你说你不好意思问我要钱。我说，我确实不好意思。她说，所以你拿三成，这三成是你自己挣的，你要钱的时候你讲话的声音就不一样。我说，你连这个都算。她说，我跟你讲话不算这个我就不讲了。她说，我不愿意有一天你跟我讲话的时候，你心里在算你欠我。她说，我这一辈子最怕的就是我对我好的人，最后变成他欠我。我说，那你别对我好。她说，我对你好什么了。我说，你处处给我想。她说，我不是给你想。她说，我是在保护我们这一单。她说，你这个人你要是一觉得你欠我，你就开始少讲话。她说，你一少讲话，我这边的单就没人接了。她说，我要你讲话。她说，我要你每天问我"这个发不发"、"这个要不要退"、"这个地址对不对"。她说，你问得越多我这边越安全。我说，你这叫雇我。她说，对。她说，我叫你干活，我给你钱，你跟我吵价钱。她说，这个关系我hold得住。她说，别的关系我今天hold不住。',-1),e("p",null,'那晚我们讲了很久价钱。我这一辈子第一次跟人坐下来吵一个价。她说三成。我说两成五。她说为什么。我说，三成我要管退件，退件不在我这边发生。她说，两成七，退件你不用管，你只负责登记。我说，登记也要时间。她说，登记一条十秒，你一天最多二十条。我说，那我一天多二十分钟。她说，二十分钟我给你两成八。我说，三成都给我登记。她笑了。她说，你这个人，你刚才两成七的时候你为什么不讲。我说，我在算你要还几轮。她说，你怎么知道我要还。我说，你讲了两次"我今天不想"，你讲"hold不住"，你要还我一次。她说，你连这个都算。我说，我干这个的。她说，行，三成。她说，加一条，你从今天起不许叫我程总。我说，我叫你什么。她说，你叫我的名字。我说，我一直叫。她说，你今天下午在店员面前差一点叫出"您"。她说，你以后在我这儿没有"您"这个字。',-1),e("p",null,"那门生意做了两年。第二年，我们从一箱五十件，做到一个月四个箱。我那时候已经在一个公司上班。我下班以后发东西。我们家那个屋子后来全部是她的货。我妈那天进我屋，她站在门口。她说，你这个屋子里已经没有你睡觉的地方了。我说，我睡那头。她说，你那个床上全是包。我说，我明天发完。我妈走进来，她在那个纸箱上坐下来。她说，你干这个一个月挣多少。我说，三千多。她说，三千多你把家里堆成这样。我说，我妈你别讲。她说，我不讲。她说，我就问你一句。我说，你说。她说，这个是你老板，还是你对象。我说，都有。我妈说，那她给你开工资吗。我说，给。她说，给钱就行。她说，我给你把那个床上的东西挪到椅子上，你别堆到地上，地上你扫地不方便。我妈那天上午把我那个屋里的箱子重新码了一遍。她码得比我对齐。她把最重的那两箱放在最底下。她在箱子边上贴了一张纸，纸上写：12月，18件。她写完她说，你这个东西要写日期，你不写日期你自己找不到。我说，我知道。她说，你不知道。她说，你要知道你就堆在地上了。那天下午我坐在我妈码好的那堆箱子前面，发了四十分钟呆。我不是在想我妈这句话。我是在想，我这辈子所有的事，最后都变成一堆码在墙角的箱子。而这些箱子里，只有我一个人知道它们是谁的。",-1),e("p",null,'那天晚上我给她发了一句。我说，你今天那个单，37号，客人打电话说地址错了。她说，我改了。我说，你改了什么。她说，我改了地址，我给她发了两条短信。我说，她没接？她说，她接了，她说她要退。我说，那退。她说，退了我这单赔十九。我说，那你也退。她说，你这个人。我说，怎么了。她说，你今天讲"那你也退"这四个字，你讲得特别顺。我说，我算过了。她说，你算了什么。我说，你今年这个月净剩八千四，赔十九你不会难受。她说，你连我这个月挣多少你都知道。我说，你每周三给我结钱，我记了两年。她说，你记这个干什么。我说，我要知道我这边一单多少钱。她说，你现在知道了，你刚才讲了一句我这辈子没听过的话。我说，哪句。她说，"那你也退"。她说，这个人讲这句话的时候，他不觉得十九块是一件事。她说，他跟我讲这个钱不是事。她说，你今天下午这句话我记一下。我说，你别记。她说，为什么。我说，你一记你就又开始算我欠你。她说，对。她说，我今天晚上开始算。',-1),e("p",null,'我们第一次结算是在一月十七。她转过来一千一百四十三块五。我算的是那一千一百四十三。多出来的五毛，我退回去。她说，你退什么。我说，多了五毛。她说，五毛你留着。我说，我不要。她说，你不要你退回来我要再收一次，我这边要点两下。我说，那你点两下。她说，你今天怎么了。我说，我今天算了一晚上这个数。她说，五毛钱你算一晚上？我说，我不是算五毛。我说，我是算你为什么要多给五毛。她隔了很久。她说，我那天算你单价的时候，我把一个退件算进去了，我没减。我说，那你现在减。她说，我减了我就要跟你讲这个事。我说，你现在讲了。她说，对。她说，我今天跟你讲这个，是因为你如果不算这五毛，你不会问。她说，你要是直接收了，我明天还得自己想起来，我今天晚上就睡不好。她说，你拿这五毛换了我一个晚上睡得着。我说，那这五毛我该拿。她说，你拿吧。我说，我还是退。她说，你退就是你不想要这个晚上睡得着的钱。我说，我退是因为这个钱不是我今天干的。她说，行。她说，我把这五毛记到下个月第一天。她说，我下个月给你多五毛，你就不好退了吧。我说，我下个月也退。她说，那我们两个今年就要为五毛讲二十分钟。我说，我讲不了二十分钟，我今天已经讲了十二分钟了。她说，那行了。她说，我知道你为什么退这五毛。我说，为什么。她说，因为这是你们家那个"不能拿不属于自己东西"的做法。她说，你拿了这个五毛，你今天晚上回去你跟我讲"我今天收了五毛"，你自己听都难看。她说，你退了你晚上就能睡着。她说，我们两个今天晚上谁也不欠谁一个晚上。那天晚上我退了那五毛。我退完我躺在床上，我确实睡得很好。',-1)])])}const f=t(o,[["render",s]]);export{u as __pageData,f as default};
